-- deadlines
CREATE TABLE IF NOT EXISTS public.deadlines (
  id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  contract_id uuid NOT NULL,
  contract_version_id uuid NOT NULL,
  obligation_id uuid,
  kind text NOT NULL DEFAULT 'unresolved',
  category text NOT NULL DEFAULT 'other',
  label text NOT NULL,
  due_date date,
  due_at timestamptz,
  timezone text NOT NULL DEFAULT 'UTC',
  anchor_event text,
  anchor_date date,
  trigger_event_id uuid,
  depends_on_deadline_id uuid,
  calculation_rule jsonb NOT NULL DEFAULT '{}'::jsonb,
  calculation_trace jsonb NOT NULL DEFAULT '[]'::jsonb,
  assumptions jsonb NOT NULL DEFAULT '[]'::jsonb,
  missing_anchors jsonb NOT NULL DEFAULT '[]'::jsonb,
  recurrence jsonb NOT NULL DEFAULT '{}'::jsonb,
  source_clause_id uuid,
  validation_status text NOT NULL DEFAULT 'pending_review',
  status text NOT NULL DEFAULT 'open',
  escalation_level integer NOT NULL DEFAULT 0,
  fingerprint text NOT NULL,
  human_modified boolean NOT NULL DEFAULT false,
  analysis_run_id uuid,
  CONSTRAINT deadlines_contract_id_fkey FOREIGN KEY (contract_id, org_id) REFERENCES public.contracts (id, org_id) ON DELETE CASCADE,
  CONSTRAINT deadlines_contract_version_id_fkey FOREIGN KEY (contract_version_id, org_id) REFERENCES public.contract_versions (id, org_id) ON DELETE CASCADE,
  CONSTRAINT deadlines_obligation_id_fkey FOREIGN KEY (obligation_id, org_id) REFERENCES public.obligations (id, org_id) ON DELETE CASCADE,
  CONSTRAINT deadlines_kind_check CHECK (kind IN ('explicit', 'derived', 'event_triggered', 'recurring', 'unresolved')),
  CONSTRAINT deadlines_category_check CHECK (category IN ('renewal_notice', 'expiration', 'termination_notice', 'payment', 'delivery', 'reporting', 'other')),
  CONSTRAINT deadlines_trigger_event_id_fkey FOREIGN KEY (trigger_event_id, org_id) REFERENCES public.events (id, org_id) ON DELETE SET NULL (trigger_event_id),
  CONSTRAINT deadlines_depends_on_deadline_id_fkey FOREIGN KEY (depends_on_deadline_id, org_id) REFERENCES public.deadlines (id, org_id) ON DELETE SET NULL (depends_on_deadline_id),
  CONSTRAINT deadlines_source_clause_id_fkey FOREIGN KEY (source_clause_id, org_id) REFERENCES public.clauses (id, org_id) ON DELETE SET NULL (source_clause_id),
  CONSTRAINT deadlines_validation_status_check CHECK (validation_status IN ('confirmed', 'pending_review', 'unresolved', 'rejected')),
  CONSTRAINT deadlines_status_check CHECK (status IN ('open', 'done', 'missed', 'waived')),
  CONSTRAINT deadlines_analysis_run_id_fkey FOREIGN KEY (analysis_run_id, org_id) REFERENCES public.analysis_runs (id, org_id) ON DELETE SET NULL (analysis_run_id),
  CONSTRAINT deadlines_id_org_key UNIQUE (id, org_id),
  CONSTRAINT deadlines_contract_version_id_fingerprint_key UNIQUE (contract_version_id, fingerprint)
);
CREATE INDEX IF NOT EXISTS idx_deadlines_org_id_due_date ON public.deadlines (org_id, due_date);
CREATE INDEX IF NOT EXISTS idx_deadlines_contract_id ON public.deadlines (contract_id);
CREATE INDEX IF NOT EXISTS idx_deadlines_obligation_id ON public.deadlines (obligation_id);
CREATE INDEX IF NOT EXISTS idx_deadlines_org_id ON public.deadlines (org_id);
CREATE INDEX IF NOT EXISTS idx_deadlines_trigger_event_id ON public.deadlines (trigger_event_id);
CREATE INDEX IF NOT EXISTS idx_deadlines_depends_on_deadline_id ON public.deadlines (depends_on_deadline_id);
CREATE INDEX IF NOT EXISTS idx_deadlines_source_clause_id ON public.deadlines (source_clause_id);
