-- analysis_findings
CREATE TABLE IF NOT EXISTS public.analysis_findings (
  id uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  contract_id uuid NOT NULL,
  contract_version_id uuid,
  run_id uuid,
  finding_type text NOT NULL DEFAULT 'risk_signal',
  severity text NOT NULL DEFAULT 'medium',
  signal_category text NOT NULL DEFAULT 'business_risk',
  title text NOT NULL,
  description text NOT NULL,
  clause_id uuid,
  obligation_id uuid,
  deadline_id uuid,
  evidence_ids jsonb NOT NULL DEFAULT '[]'::jsonb,
  contributions jsonb NOT NULL DEFAULT '{}'::jsonb,
  weight double precision NOT NULL DEFAULT 0.0,
  status text NOT NULL DEFAULT 'open',
  review_status text NOT NULL DEFAULT 'unreviewed',
  confidence double precision NOT NULL DEFAULT 0.0,
  fingerprint text NOT NULL,
  CONSTRAINT analysis_findings_contract_id_fkey FOREIGN KEY (contract_id, org_id) REFERENCES public.contracts (id, org_id) ON DELETE CASCADE,
  CONSTRAINT analysis_findings_contract_version_id_fkey FOREIGN KEY (contract_version_id, org_id) REFERENCES public.contract_versions (id, org_id) ON DELETE SET NULL (contract_version_id),
  CONSTRAINT analysis_findings_run_id_fkey FOREIGN KEY (run_id, org_id) REFERENCES public.analysis_runs (id, org_id) ON DELETE SET NULL (run_id),
  CONSTRAINT analysis_findings_finding_type_check CHECK (finding_type IN ('risk_signal', 'missing_information', 'ambiguity', 'conflict', 'unassigned_obligation', 'deadline_exposure', 'playbook_deviation', 'unsupported_claim', 'extraction_quality', 'prompt_injection', 'amendment_change')),
  CONSTRAINT analysis_findings_severity_check CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
  CONSTRAINT analysis_findings_signal_category_check CHECK (signal_category IN ('business_risk', 'extraction_uncertainty')),
  CONSTRAINT analysis_findings_clause_id_fkey FOREIGN KEY (clause_id, org_id) REFERENCES public.clauses (id, org_id) ON DELETE SET NULL (clause_id),
  CONSTRAINT analysis_findings_obligation_id_fkey FOREIGN KEY (obligation_id, org_id) REFERENCES public.obligations (id, org_id) ON DELETE SET NULL (obligation_id),
  CONSTRAINT analysis_findings_deadline_id_fkey FOREIGN KEY (deadline_id, org_id) REFERENCES public.deadlines (id, org_id) ON DELETE SET NULL (deadline_id),
  CONSTRAINT analysis_findings_status_check CHECK (status IN ('open', 'acknowledged', 'resolved', 'dismissed')),
  CONSTRAINT analysis_findings_review_status_check CHECK (review_status IN ('unreviewed', 'needs_review', 'approved', 'rejected', 'corrected')),
  CONSTRAINT analysis_findings_id_org_key UNIQUE (id, org_id),
  CONSTRAINT analysis_findings_contract_id_fingerprint_key UNIQUE (contract_id, fingerprint)
);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_org_id_status ON public.analysis_findings (org_id, status);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_org_id ON public.analysis_findings (org_id);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_contract_version_id ON public.analysis_findings (contract_version_id);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_run_id ON public.analysis_findings (run_id);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_clause_id ON public.analysis_findings (clause_id);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_obligation_id ON public.analysis_findings (obligation_id);
CREATE INDEX IF NOT EXISTS idx_analysis_findings_deadline_id ON public.analysis_findings (deadline_id);
