CREATE TRIGGER trg_audit_logs_updated_at BEFORE UPDATE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- circular references added after all tables exist

ALTER TABLE public.contracts DROP CONSTRAINT IF EXISTS contracts_current_version_id_fkey;
ALTER TABLE public.contracts ADD CONSTRAINT contracts_current_version_id_fkey FOREIGN KEY (current_version_id, org_id) REFERENCES public.contract_versions (id, org_id) ON DELETE SET NULL (current_version_id);
